            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Font Size</h5>
                    <div class="d-flex gap-3">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(FontSize == size)"
                                       @onchange="() => FontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>
            </div>

            <!-- Language -->
            <div class="card mb-4">
                <div class="card-body">
                    <h5 class="card-title">Language</h5>
                    <select class="form-select" @bind="Language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>
            </div>

            <!-- Compact Mode -->
            <div class="card mb-4">
                <div class="card-body">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="CompactMode" />
                        <label class="form-check-label" for="compactMode">
                            <strong>Compact Mode</strong>
                            <div class="form-text">Reduce spacing and padding for denser content</div>
                        </label>
                    </div>
                </div>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card sticky-top" style="top: 1rem;">
                <div class="card-header">
                    <h5 class="mb-0">Live Preview</h5>
                </div>
                <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                    <h6 style="@GetFontStyle()">Sample Heading</h6>
                    <p style="@GetFontStyle()" class="@(CompactMode ? "mb-1" : "mb-3")">
                        This is how your content will look with the selected settings.
                    </p>
                    <div class="d-flex gap-2 @(CompactMode ? "mb-1" : "mb-3")">
                        <button class="btn btn-sm btn-primary">Primary</button>
                        <button class="btn btn-sm btn-outline-secondary">Secondary</button>
                    </div>
                    <div class="@(CompactMode ? "p-1" : "p-2") rounded" style="@GetPreviewCardStyle()">
                        <small style="@GetFontStyle()">A nested card element</small>
                    </div>
                </div>
            </div>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(SuccessMessage))
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            @SuccessMessage
            <button type="button" class="btn-close" @onclick="() => SuccessMessage = null"></button>
        </div>
    }

    <button class="btn btn-primary" @onclick="Save" disabled="@IsSaving">
        @if (IsSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save
    </button>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "System";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public string Language { get; set; } = "en";
    [Parameter] public bool CompactMode { get; set; }
    [Parameter] public EventCallback<(string Theme, string FontSize, string Language, bool CompactMode)> OnSave { get; set; }

    private string? SuccessMessage;
    private bool IsSaving;

    private string GetPreviewClasses()
    {
        return Theme == "Dark" ? "bg-dark text-light" : "bg-light text-dark";
    }

    private string GetPreviewStyles()
    {
        var padding = CompactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";
        return $"min-height: 200px; transition: all 0.3s ease; {padding}";
    }

    private string GetFontStyle()
    {
        var size = FontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size: {size};";
    }

    private string GetPreviewCardStyle()
    {
        return Theme == "Dark"
            ? "background-color: #333; border: 1px solid #555;"
            : "background-color: #fff; border: 1px solid #dee2e6;";
    }

    private async Task Save()
    {
        IsSaving = true;
        await OnSave.InvokeAsync((Theme, FontSize, Language, CompactMode));
        IsSaving = false;
        SuccessMessage = "Appearance settings saved!";
        _ = DismissAfterDelay();
    }

    private async Task DismissAfterDelay()
    {
        await Task.Delay(3000);
        SuccessMessage = null;
        StateHasChanged();
    }
}
"}

