@page "/settings"
@using sv_fa2a221be80d49a5a114b19dfedd9ec9.Components.Pages.Settings
@using sv_fa2a221be80d49a5a114b19dfedd9ec9.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <div class="settings-sidebar">
        <SettingsNavigation ActiveSection="@ActiveSection" OnSectionChanged="SetActiveSection" />
    </div>

    <div class="settings-content">
        @if (IsLoading)
        {
            <div class="d-flex justify-content-center align-items-center" style="min-height: 300px;">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    <ProfileSection
                        DisplayName="@Profile.DisplayName"
                        Email="@Profile.Email"
                        AvatarUrl="@Profile.AvatarUrl"
                        Bio="@Profile.Bio"
                        OnSave="SaveProfile"
                        OnDiscard="DiscardProfile" />
                    break;

                case "Notifications":
                    <NotificationsSection
                        EmailNotifications="@NotifPrefs.EmailNotifications"
                        PushNotifications="@NotifPrefs.PushNotifications"
                        WeeklyDigest="@NotifPrefs.WeeklyDigest"
                        MutedChannels="@NotifPrefs.MutedChannels.ToList()"
                        AvailableChannels="@AvailableChannels"
                        OnSave="SaveNotifications" />
                    break;

                case "Security":
                    <SecuritySection
                        TwoFactorEnabled="@Security.TwoFactorEnabled"
                        LastPasswordChange="@Security.LastPasswordChange"
                        Sessions="@Security.Sessions"
                        CurrentSessionId="@CurrentSessionId"
                        OnChangePassword="ChangePassword"
                        OnRevokeSession="RevokeSession"
                        OnToggle2FA="Toggle2FA" />
                    break;

                case "Appearance":
                    <AppearanceSection
                        Theme="@Appearance.Theme"
                        FontSize="@Appearance.FontSize"
                        Language="@Appearance.Language"
                        CompactMode="@Appearance.CompactMode"
                        OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile Profile = new("", "", "", "");
    private UserProfile SavedProfile = new("", "", "", "");
    private NotificationPrefs NotifPrefs = new(false, false, false, new());
    private SecuritySettings Security = new(false, null, new());
    private AppearanceSettings Appearance = new("System", "Medium", "en", false);

    private string CurrentSessionId = "";
    private List<string> AvailableChannels = new() { "General", "Announcements", "Updates", "Marketing", "Engineering" };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllData();
        IsLoading = false;
    }

    private async Task LoadAllData()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        Profile = await profileTask;
        SavedProfile = Profile;
        NotifPrefs = await notifTask;
        Security = await securityTask;
        Appearance = await appearanceTask;

        if (Security.Sessions.Count > 0)
            CurrentSessionId = Security.Sessions[0].Id;
    }

    private void SetActiveSection(string section)
    {
        ActiveSection = section;
    }

    private async Task SaveProfile((string DisplayName, string Email, string AvatarUrl, string Bio) data)
    {
        Profile = new UserProfile(data.DisplayName, data.Email, data.AvatarUrl, data.Bio);
        await SettingsService.SaveProfileAsync(Profile);
        SavedProfile = Profile;
    }

    private void DiscardProfile()
    {
        Profile = SavedProfile;
    }

    private async Task SaveNotifications((bool Email, bool Push, bool Digest, List<string> Muted) data)
    {
        NotifPrefs = new NotificationPrefs(data.Email, data.Push, data.Digest, data.Muted);
        await SettingsService.SaveNotificationPrefsAsync(NotifPrefs);
    }

    private async Task ChangePassword((string Current, string New) data)
    {
        await SettingsService.ChangePasswordAsync(data.Current, data.New);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        Security = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task Toggle2FA(bool enabled)
    {
        Security = Security with { TwoFactorEnabled = enabled };
        // In a real app, this would call a service method
    }

    private async Task SaveAppearance((string Theme, string FontSize, string Language, bool CompactMode) data)
    {
        Appearance = new AppearanceSettings(data.Theme, data.FontSize, data.Language, data.CompactMode);
        await SettingsService.SaveAppearanceAsync(Appearance);
    }
}

.settings-page {
    display: flex;
    gap: 2rem;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.settings-sidebar {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-nav .nav-link {
    border-radius: 0.5rem;
    padding: 0.75rem 1rem;
    color: #495057;
    font-weight: 500;
    transition: all 0.2s ease;
}

.settings-nav .nav-link:hover {
    background-color: #f8f9fa;
    color: #212529;
}

.settings-nav .nav-link.active {
    background-color: #0d6efd;
    color: white;
}

@@media (max-width: 768px) {
    .settings-page {
        flex-direction: column;
        gap: 1rem;
    }

    .settings-sidebar {
        flex: none;
    }

    .settings-nav .nav {
        flex-direction: row !important;
        overflow-x: auto;
    }

    .settings-nav .nav-item {
        flex: none;
    }
}

