    border-radius: 0.5rem;
    padding: 0.75rem 1rem;
    color: #495057;
    font-weight: 500;
    transition: all 0.2s ease;
}

.settings-nav .nav-link:hover {
    background-color: #f8f9fa;
    color: #212529;
}

.settings-nav .nav-link.active {
    background-color: #0d6efd;
    color: white;
}

